-- 公开参考音色：181 条音频 + 181 条缩略图
-- 方舟国内 ark-cn 80 条，BytePlus byteplus 101 条。
--
-- 用法：psql "$APP_DATABASE_DSN" -f seed/official-voices/assets.sql
--
-- 前置两件事，缺一样就会出现"有记录没声音"：
--   1) 音频与缩略图已按 storage_key 放进默认存储（本地磁盘解包即可，对象存储需同步上传，见 README）；
--   2) 库里已有默认存储配置（首次启动会自动建内置本地磁盘，或在后台「存储配置」里指定）。
--
-- 幂等：按键名 storage_key 与官方素材 ID 双重判重，重复执行不会多出行；
-- 记录一律落在默认存储上，storage_id 从 storage_configs 现查，不写死。
BEGIN;

-- 目标存储：默认存储。没有默认存储直接报错，避免把记录写到不确定的地方。
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM storage_configs WHERE is_default) THEN
    RAISE EXCEPTION '没有默认存储配置：先在后台「存储配置」里指定一个默认存储';
  END IF;
END $$;

CREATE TEMP TABLE voice_seed (
  source text, storage_key text, mime_type text, byte_size bigint,
  width int, height int, duration_ms bigint, file_name text, sha256 text,
  thumbnail_key text, official_asset_id text, official_scope text,
  voice_age text, voice_gender text, voice_lang text
) ON COMMIT DROP;


                    width, height, duration_ms, source, file_name, sha256,
                    thumbnail_key, official_asset_id, official_channel_key,
                    official_scope, voice_age, voice_gender, voice_lang, created_at)
SELECT 0,
       CASE v.source WHEN 'official' THEN 'audio' ELSE 'image' END,
       s.id, v.storage_key, v.mime_type, v.byte_size, v.width, v.height, v.duration_ms,
       v.source, v.file_name, v.sha256, v.thumbnail_key, v.official_asset_id,
       '', v.official_scope, v.voice_age, v.voice_gender, v.voice_lang, now()
FROM voice_seed v
CROSS JOIN (SELECT id FROM storage_configs WHERE is_default LIMIT 1) s
WHERE NOT EXISTS (SELECT 1 FROM assets a WHERE a.storage_key = v.storage_key)
  AND (v.source <> 'official'
       OR NOT EXISTS (SELECT 1 FROM assets a WHERE a.official_asset_id = v.official_asset_id
                        AND a.source = 'official'));

-- 核对一：数据包里的 362 条记录是否都落到了库里。少一条就整体回滚，避免发版后才发现缺音色。
DO $$
DECLARE missing int;
BEGIN
  SELECT count(*) INTO missing
  FROM voice_seed v
  WHERE NOT EXISTS (SELECT 1 FROM assets a WHERE a.storage_key = v.storage_key);
  IF missing > 0 THEN
    RAISE EXCEPTION '导入不完整：还有 % 条记录没写进库（键名或官方 ID 与已有数据冲突）', missing;
  END IF;
  RAISE NOTICE '导入完成：362 条记录（181 条音色 + 181 张缩略图）已就位';
END $$;

-- 核对二：当前库里公开音色的总数，正常是 181 / 181
SELECT count(*) FILTER (WHERE source = 'official')       AS voices,
       count(*) FILTER (WHERE source = 'official_thumb') AS thumbnails
FROM assets;

COMMIT;
